package co.com.empresa.infrastructure.config.kafka;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.serialization.StringSerializer;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.springframework.boot.kafka.autoconfigure.KafkaProperties;import org.springframework.kafka.core.DefaultKafkaProducerFactory;import org.springframework.kafka.support.serializer.JacksonJsonSerializer;import java.util.Map;import static org.junit.jupiter.api.Assertions.assertEquals;import static org.junit.jupiter.api.Assertions.assertNotNull;class KafkaProducerConfigTest {    private KafkaProperties kafkaProperties;    private KafkaConfig kafkaConfig;    @BeforeEach    void setUp() {        kafkaProperties = new KafkaProperties();        kafkaConfig = new KafkaConfig(kafkaProperties);    }    @Test    @DisplayName("producerFactory: Should configure key serializer as StringSerializer")    void producerFactory_ConfiguresKeySerializer() {        DefaultKafkaProducerFactory<String, Object> factory = (DefaultKafkaProducerFactory<String, Object>) kafkaConfig.producerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals(StringSerializer.class, configs.get(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG),                "Key serializer should be StringSerializer");    }    @Test    @DisplayName("producerFactory: Should configure value serializer as JacksonJsonSerializer")    void producerFactory_ConfiguresValueSerializer() {        DefaultKafkaProducerFactory<String, Object> factory = (DefaultKafkaProducerFactory<String, Object>) kafkaConfig.producerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals(JacksonJsonSerializer.class, configs.get(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG),                "Value serializer should be JacksonJsonSerializer");    }    @Test    @DisplayName("kafkaTemplate: Should use the same producerFactory")    void kafkaTemplate_UsesProducerFactory() {        var template = kafkaConfig.kafkaTemplate();        var factory = kafkaConfig.producerFactory();        assertNotNull(template.getProducerFactory(), "KafkaTemplate should have a ProducerFactory");    }}